"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 leak check (plan 8.2, 8.6; step 0 item 12). Every assertion must pass before any training or test run.

Reads only metadata (meta.jsonl of the rendered splits and the step-0 split files), never audio or system outputs:
  - recording groups (v0.3 pools, new classes, Freesound doors, the Freesound subset) each lie in one split, and every
    clip a unit uses comes from its own split; no MUSAN-matched clip and none of the three dropped Freesound clips;
  - user, visitor and TV-TTS voices, Piper speakers, rooms and noise environments come from the unit's split; the
    assistant's Piper speaker is never a user voice;
  - every line a unit speaks is a common line (flip lines, backchannels), a pool line of its split, its conversation's
    own line, or an episode script line of its split;
  - TV recordings come from speakers of the unit's split;
  - recording-group caps per part and recording type (dev 30%, test and replication 15%, never below 1/number of
    groups; + 0.05 tolerance; door sounds typed by source, as the planner caps them: p1v4_units.cap_type);
  - the situation text does not depend on gold labels (built with and without them: identical).
usage: python -I scripts/p1v4_leak_check.py <render dir> [<render dir> ...]
"""
import copy
import json
import os
import sys
from collections import Counter, defaultdict

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_situation as SIT  # noqa: E402
import p1v4_units as U  # noqa: E402

CAP = {"train": 1.0, "dev": 0.30, "test": 0.15, "replication": 0.15}


def main(dirs):
    fails = []
    assets = {}
    # 1. each recording group in one split
    group_splits = defaultdict(set)
    for sp in ("train", "dev", "test", "replication"):
        A = assets[sp] = U.Assets(sp)
        for path, g in A.group.items():
            group_splits[g].add(sp)
    for g, s in group_splits.items():
        if len(s) > 1:
            fails.append(f"group {g} in {sorted(s)}")
    musan = set(json.load(open("results/step0/musan_matches.json"))["excluded_clips"]) | set(
        json.load(open("results/step0_v04/new_check.json"))["musan_excluded"])
    eps = U.load_episode_scripts()            # the renderer's files and order (a glob also took the pilot file)
    n_rows = 0
    use = defaultdict(Counter)
    for d in dirs:
        rows = [json.loads(line) for line in open(os.path.join(d, "meta.jsonl"), encoding="utf-8")]
        for r in rows:
            n_rows += 1
            sp = r["unit"].split("_d")[0]
            A = assets[sp]
            spec = r["spec"]
            allowed_text = set(A.flip["phone"]["common"] + A.flip["phone"]["test_only"] + A.flip["door"]["common"]
                               + A.backchannel)
            for k in A.pool:
                allowed_text |= {x["line"] for x in A.pool[k]}
            conv = A.convs[spec["conv"]] if spec.get("conv") is not None else {}
            allowed_text |= {conv.get(x) for x in ("user_request", "agent_answer", "user_followup")}
            fu = conv.get("user_followup")
            if fu:                                     # barge-in checks: the follow-up with an opener (plan_floor)
                allowed_text |= {o + fu[0].lower() + fu[1:] for o in U.BARGE_OPENERS}
            for w in ("phone", "door"):
                allowed_text |= set(A.reject[w].get(spec["conv"], {}).values())
            for k in ("he_door", "he_phone", "b2_side"):
                allowed_text |= set(A.v3lines[k])
            allowed_text |= {x for p in A.v3lines["f3_pair"] for x in (p["family_call"], p["user_reply"])}
            allowed_text |= set(U.VISITOR_OPENERS)
            if r["part"] == "episode":
                allowed_text |= {t["text"] for t in eps.get(spec["episode"], []) if t["kind"] == "speech"}
            if spec.get("tv_text"):
                allowed_text.add(spec["tv_text"])
            for s in r["sources"]:
                path = s.get("path")
                if path:
                    if path not in A.group:
                        fails.append(f"{r['unit']}: {path} not an asset of {sp}")
                    if os.path.splitext(os.path.basename(path))[0] in musan:
                        fails.append(f"{r['unit']}: MUSAN-matched clip {path}")
                    if any(x in path for x in U.FS_NEW_DROP):
                        fails.append(f"{r['unit']}: dropped Freesound clip {path}")
                if s["kind"] == "speech":
                    v = s["voice"]
                    if v.get("engine") == "kokoro" and v["voice"] not in A.voices:
                        fails.append(f"{r['unit']}: voice {v['voice']} not in {sp}")
                    if v.get("engine") == "piper" and s["who"] != "assistant" and int(v["speaker"]) not in A.piper:
                        fails.append(f"{r['unit']}: piper speaker {v['speaker']} not in {sp}")
                    if s["text"] not in allowed_text:
                        fails.append(f"{r['unit']}: line not from its split: {s['text'][:60]}")
                if s.get("rir"):
                    size = "smallroom" if spec["room"].startswith("small") else "mediumroom"
                    if f"{size}/{spec['room'].split('-')[1]}/" not in s["rir"]:
                        fails.append(f"{r['unit']}: RIR outside the unit's room")
            if spec["room"] not in A.rooms:
                fails.append(f"{r['unit']}: room {spec['room']} not in {sp}")
            if not any(e in spec["noise"] for e in A.envs):
                fails.append(f"{r['unit']}: noise {spec['noise']} not in {sp}")
            if r["version"] == "1" or r["part"] in ("s_move", "s_react", "r_hear"):
                for s in r["sources"]:                 # caps per part and recording type (plan 5.6)
                    if s.get("path") in A.group:
                        cls = U.cap_type(s, A)                    # door sounds by source (planner's cap keys)
                        use[(sp, d, r["part"], cls, A.group[s["path"]])][r["unit"]] += 1
            for k, p in enumerate(r["points"]):
                tr = {s["id"]: "x" for s in r["sources"]}
                tags = {s["id"]: "user" for s in r["sources"]}
                a = SIT.build(r, k, tr, tags, [])
                r2 = copy.deepcopy(r)
                r2["points"][k]["gold"] = None
                if SIT.build(r2, k, tr, tags, []) != a:
                    fails.append(f"{r['unit']}: situation text depends on gold")
        # caps: among a part's units that use a recording type, the share that uses one group of that type
        by_cls = defaultdict(set)
        n_groups = Counter()
        for (sp, dd, part, cls, g), c in use.items():
            if dd == d:
                by_cls[(sp, part, cls)] |= set(c)
                n_groups[(sp, part, cls)] += 1
        for (sp, dd, part, cls, g), c in use.items():
            if dd != d or sp == "train":
                continue
            share = len(c) / max(1, len(by_cls[(sp, part, cls)]))
            cap = max(CAP[sp], 1 / max(1, n_groups[(sp, part, cls)]))
            if share > cap + 0.05:
                fails.append(f"cap: {sp} {part} {cls} group {g} share {share:.2f} > {cap:.2f}")
    print(f"checked {n_rows} unit versions in {len(dirs)} render dirs")
    print("PASS" if not fails else f"FAIL ({len(fails)}):")
    kinds = Counter(f.split(": ", 1)[1].split(":")[0][:40] if ": " in f else f.split(" ")[0] for f in fails)
    for k, n in kinds.most_common():
        print(f"   {n:5d}  {k}")
    for f in fails[:40]:
        print("  ", f)
    return not fails


if __name__ == "__main__":
    sys.exit(0 if main(sys.argv[1:]) else 1)
